import{_ as o,o as a,c as n,a0 as s}from"./chunks/framework.C3yZ6M33.js";const u=JSON.parse('{"title":"Run CI through ci-job entities","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/run-ci-through-ci-job-entities.md","filePath":"how-to/run-ci-through-ci-job-entities.md"}'),t={name:"how-to/run-ci-through-ci-job-entities.md"};function i(c,e,d,r,l,h){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="run-ci-through-ci-job-entities" tabindex="-1">Run CI through <code>ci-job</code> entities <a class="header-anchor" href="#run-ci-through-ci-job-entities" aria-label="Permalink to &quot;Run CI through \`ci-job\` entities&quot;">​</a></h1><p>Production CI ingress is a peregrin campaign: a verified forge webhook becomes a <code>kind=&quot;ci-job&quot;</code> entity on the node, and bupha workers claim and execute it. This guide wires the shipped <code>ci-ingress</code> bundle end to end. For the worker side (fleet config, <code>tamias-driver-bupha worker</code>), see bupha&#39;s docs; for running the webhook listener itself, see <a href="/peregrin/how-to/serve-campaigns.html">Serve campaigns</a>.</p><h2 id="the-shape" tabindex="-1">The shape <a class="header-anchor" href="#the-shape" aria-label="Permalink to &quot;The shape&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>github webhook ──► github-webhook node ──► push / pull_request event</span></span>
<span class="line"><span>                                            │</span></span>
<span class="line"><span>                          ci.route (typed re-emit)  ◄──┘</span></span>
<span class="line"><span>                                            ▼</span></span>
<span class="line"><span>                          ci.enqueue / ci.enqueue.pr   (driver: http)</span></span>
<span class="line"><span>                                            │  POST /api/entities</span></span>
<span class="line"><span>                                            ▼</span></span>
<span class="line"><span>                    peregrin node — CiJobPlane (kind=&quot;ci-job&quot;)</span></span>
<span class="line"><span>                                            │</span></span>
<span class="line"><span>                  tamias-driver-bupha worker ── ci.claim/renew/complete</span></span></code></pre></div><p><code>libraries/ci-ingress/main.yaml</code> is a complete campaign: the <code>github-webhook</code> ingress node (HMAC-verified, one <code>secret_env</code> per watched repo), <code>ci.route</code> re-emitting typed events (<code>{type}.{repo}.{ref}.{clone_url}.{sha}</code>), and <code>driver: http</code><code>ci.enqueue*</code> nodes that POST the indexDoc to <code>\${config.node_url}/api/entities</code>. <strong>Create IS <code>ci.enqueue</code></strong> — the deterministic entity id <code>ci:{key}:{sha}:{attempt}</code> dedups webhook replays for free, and both enqueue nodes set <code>retries: 3</code> since a re-POST is idempotent.</p><h2 id="deploy-the-campaign" tabindex="-1">Deploy the campaign <a class="header-anchor" href="#deploy-the-campaign" aria-label="Permalink to &quot;Deploy the campaign&quot;">​</a></h2><p>The plane lives on the node: <code>peregrin serve</code> registers <code>bupha_plane::CiJobPlane</code> behind the default-on <code>bupha</code> cargo feature. Deploy the bundle through tamias — it renders into the <strong>shared</strong> <code>peregrin-campaign.service</code> (every <code>peregrin-bundle</code> declares <code>provider.name: peregrin</code>, one listener, one history dir):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./libraries/ci-ingress</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # or a git:/registry ref</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci-ingress</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # → ~/.config/peregrin/serve/ci-ingress.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> peregrin-campaign.service</span></span></code></pre></div><p><code>~/.config/peregrin/env</code> needs <code>PEREGRIN_NODE_TOKEN</code> (bearer for the node&#39;s <code>/api/entities</code>) plus one <code>BUPHA_WH_&lt;OWNER&gt;_&lt;REPO&gt;</code> HMAC secret per watched repo — secret <strong>names</strong> only, values never in the campaign. <code>config.node_url</code> in the bundle points the enqueue POST at the plane&#39;s node (<code>http://127.0.0.1:7700</code> in the shipped params).</p><p>Operator knobs (<code>params.schema.json</code>): <code>node_url</code>, <code>queue</code> (<code>latest</code> = one pending slot per key, newest push wins; <code>all</code> = bounded FIFO, <code>MAX_PENDING=32</code>), and <code>context</code> (forge status label prefix, default <code>ci/bupha</code>).</p><h2 id="the-ci-job-lifecycle" tabindex="-1">The <code>ci-job</code> lifecycle <a class="header-anchor" href="#the-ci-job-lifecycle" aria-label="Permalink to &quot;The \`ci-job\` lifecycle&quot;">​</a></h2><p>The indexDoc <em>is</em> the job spec — <code>state</code>, <code>fence</code>, <code>leaseExpiresAt</code>, <code>claimedBy</code>, <code>runsOn</code>, <code>queue</code>, <code>runner</code>, <code>context</code>, <code>maxAttempts</code> all live on the entity:</p><ul><li><strong><code>pending</code></strong> — created by <code>POST /api/entities</code> (or requeued by <code>ci.enqueue {attempt?}</code> on a terminal/superseded entity). A spec-armed plane normalizes scheduling fields from the fleet config at create and 400s a job whose <code>ref</code>/<code>event</code> the repo spec doesn&#39;t cover.</li><li><strong><code>running</code></strong> — <code>ci.claim {worker, leaseSecs?}</code> CAS <code>pending→running</code>: sets <code>claimedBy</code>, bumps <code>fence</code>, stamps <code>leaseExpiresAt</code>/<code>startedAt</code>. A claim that loses the race is a 409. The worker renews via <code>ci.renew</code> mid-run (default lease 300s, <code>BUPHA_ENTITY_LEASE_SECS</code>); a dead worker&#39;s job returns to <code>pending</code> when the lease lapses.</li><li><strong>terminal</strong> — <code>ci.complete {worker, fence, result}</code> lands <code>success</code>/<code>failure</code>/<code>cancelled</code>/<code>error</code> (result <code>superseded</code> marks a job a newer push replaced — the &quot;latest&quot; lane policy). <code>ci.release</code> hands a running job back gracefully; <code>ci.cancel</code> settles pending on the spot or flags a running job (<code>cancelRequested</code> — the worker&#39;s renew loop observes it). <code>ci.status {queuePosition?}</code> is the rich read.</li></ul><p>Workers poll pending entities, claim what their fleet keys + labels cover, and settle — status posting stays worker-side (forge creds never leave runner boxes).</p><p><strong>Fork PRs</strong>: <code>ci.enqueue.pr</code> also sets the indexDoc&#39;s optional <code>cloneUrl</code>/<code>headRef</code> from the webhook payload&#39;s <code>head_clone_url</code> / head <code>ref</code> — populated only when the PR head lives on a fork. The worker fetches <code>git fetch &lt;cloneUrl&gt; &lt;headRef&gt;</code> (then the bare sha) before falling back to the repo&#39;s own remote, so fork heads that aren&#39;t in the base clone still check out. Pushes and same-repo PRs leave both fields absent.</p><h2 id="fleet-normalization-and-runson" tabindex="-1">Fleet normalization and <code>runsOn</code> <a class="header-anchor" href="#fleet-normalization-and-runson" aria-label="Permalink to &quot;Fleet normalization and \`runsOn\`&quot;">​</a></h2><p>Job specs live in <strong>fleet.toml</strong>, not the campaign: <code>peregrin serve</code> loads every visible bupha fleet config — <code>PEREGRIN_BUPHA_CONFIG</code> / <code>BUPHA_CONFIG</code> (file or dir) plus <code>~/.config/bupha/bundles/*.{toml,yaml,yml}</code> — and arms the plane with <code>CiJobPlane::with_watched</code>. A <code>key</code> matching a fleet spec gets <code>queue</code>/<code>runsOn</code>/<code>runner</code>/<code>context</code>/<code>maxAttempts</code> overwritten at create; unmatched keys keep the indexDoc&#39;s values. Repos needing a per-job lane declare <code>[[repo.jobs]]</code> and get their own typed-event enqueue node (see the shipped <code>ci.enqueue.job.9aia-bupha-docs</code>).</p><p><code>runs_on</code> on a fleet <code>[[repo]]</code>/<code>[[repo.jobs]]</code> entry becomes the entity&#39;s <code>runsOn</code>. A worker claims only jobs whose <code>runsOn</code> ⊆ its <code>[worker] labels</code>; unlabeled jobs are claimable by anyone. The node re-checks the same gate against its advertised capability labels — <code>PEREGRIN_RUNNER_LABELS</code> on the node is how a bupha worker&#39;s labels ride the same <code>runs_on</code> machinery campaign scheduling uses.</p><h2 id="rehydration-after-a-node-restart" tabindex="-1">Rehydration after a node restart <a class="header-anchor" href="#rehydration-after-a-node-restart" aria-label="Permalink to &quot;Rehydration after a node restart&quot;">​</a></h2><p>The sync direction is node→hub; nothing pushes entities back. At boot, before the listener binds, the node rebuilds the ci-job plane from the hub&#39;s durable entity index when <code>PEREGRIN_SNAPSHOT_TARGET</code> points at a surviving peer/hub (<code>PEREGRIN_SNAPSHOT_TOKEN</code> as bearer — the same vars the ephemeral shutdown flush uses). Only this node&#39;s bucket is read; an unreachable target logs a warning and the plane boots empty. This is why a restarted plane doesn&#39;t lose pending jobs or let the hub reconcile-tombstone them.</p><h2 id="campaigns-vs-the-entity-plane" tabindex="-1">Campaigns vs. the entity plane <a class="header-anchor" href="#campaigns-vs-the-entity-plane" aria-label="Permalink to &quot;Campaigns vs. the entity plane&quot;">​</a></h2><p>The ingress is itself a campaign — it rides the shared <code>peregrin-campaign.service</code> listener alongside every other <code>peregrin-bundle</code>, demuxed by repo on the one <code>--listen/--path</code> socket. <code>kind=&quot;ci-job&quot;</code> entities are a different kind plane on the same node (<code>peregrin serve</code>), not campaign entities — campaigns schedule via <code>runs_on</code> over <code>/api/node</code> capabilities, ci-jobs via <code>runsOn</code> over the same label list plus the worker&#39;s own <code>[worker] labels</code>. Both reuse one capability-label vocabulary.</p>`,22)])])}const g=o(t,[["render",i]]);export{u as __pageData,g as default};
